import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/foundation.dart';

/// Initializes Firebase with placeholder credentials.
///
/// In production, replace the placeholder [FirebaseOptions] below with the
/// values generated by `flutterfire configure` for your Firebase project.
/// Placeholder values will cause Firebase to fail at runtime, but the
/// exception is caught so the app continues running and other features
/// (e.g. MethodChannel, local notifications) can still be demonstrated.
class FirebaseSetup {
  static Future<void> initialize() async {
    try {
      await Firebase.initializeApp(
        options: const FirebaseOptions(
          apiKey: 'demo',
          appId: 'demo',
          projectId: 'demo',
        ),
      );
    } catch (e) {
      // Firebase initialization failed — expected with placeholder credentials.
      // The app continues without Firebase so non-Firebase features work.
    }

    if (!kIsWeb) {
      try {
        await FirebaseMessaging.instance.requestPermission(
          alert: true,
          badge: true,
          sound: true,
        );
      } catch (e) {
        // Permission request failed — non-fatal.
      }
    }
  }
}
